  ('life-lang-004', 1, 'in_review', array['lifelong']::text[], 'malay_language', 'Bahasa Melayu asas', 'Nombor', 2, 'apply', 'fill_blank', 'Satu, dua, ___, empat. (Write the missing number in Malay.)', null, null, 'Count in Malay.', 'Bahasa Melayu for beginners (CEFR A1), for learners new to Malay.', null, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('life-lang-005', 1, 'in_review', array['lifelong']::text[], 'malay_language', 'Bahasa Melayu asas', 'Keluarga', 1, 'apply', 'mcq', 'What does "ibu" mean?', '[{"id":"a","text":"father"},{"id":"b","text":"sister"},{"id":"c","text":"mother"}]'::jsonb, null, 'Name family members in Malay.', 'Bahasa Melayu for beginners (CEFR A1), for learners new to Malay.', null, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('life-lang-006', 1, 'in_review', array['lifelong']::text[], 'malay_language', 'Bahasa Melayu asas', 'Makanan', 1, 'understand', 'true_false', 'True or false: "nasi" means rice.', null, null, 'Name everyday foods in Malay.', 'Bahasa Melayu for beginners (CEFR A1), for learners new to Malay.', null, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('life-lang-007', 1, 'in_review', array['lifelong']::text[], 'malay_language', 'Bahasa Melayu asas', 'Makanan', 2, 'apply', 'mcq', 'You are hungry. Which sentence fits?', '[{"id":"a","text":"Saya lapar."},{"id":"b","text":"Saya haus."},{"id":"c","text":"Saya penat."}]'::jsonb, null, 'Say how you feel in Malay.', 'Bahasa Melayu for beginners (CEFR A1), for learners new to Malay.', null, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('life-lang-008', 1, 'in_review', array['lifelong']::text[], 'malay_language', 'Bahasa Melayu asas', 'Ayat', 2, 'apply', 'ordering', 'Put the words in order: "My name is Adam."', '[{"id":"a","text":"saya"},{"id":"b","text":"Adam."},{"id":"c","text":"Nama"}]'::jsonb, null, 'Introduce yourself in Malay.', 'Bahasa Melayu for beginners (CEFR A1), for learners new to Malay.', null, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('life-lang-009', 1, 'in_review', array['lifelong']::text[], 'malay_language', 'Bahasa Melayu asas', 'Pasar', 2, 'apply', 'mcq', 'At the market you ask "How much is this?". You say…', '[{"id":"a","text":"Di mana tandas?"},{"id":"b","text":"Berapa harga ini?"},{"id":"c","text":"Apa khabar?"}]'::jsonb, null, 'Ask prices in Malay.', 'Bahasa Melayu for beginners (CEFR A1), for learners new to Malay.', null, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('life-lang-010', 1, 'in_review', array['lifelong']::text[], 'malay_language', 'Bahasa Melayu asas', 'Warna', 2, 'apply', 'fill_blank', 'The Malay word for "red" is ___.', null, null, 'Name colours in Malay.', 'Bahasa Melayu for beginners (CEFR A1), for learners new to Malay.', null, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('life-lang-011', 1, 'in_review', array['lifelong']::text[], 'malay_language', 'Bahasa Melayu asas', 'Masa', 2, 'apply', 'mcq', 'What does "esok" mean?', '[{"id":"a","text":"yesterday"},{"id":"b","text":"today"},{"id":"c","text":"tomorrow"}]'::jsonb, null, 'Use time words in Malay.', 'Bahasa Melayu for beginners (CEFR A1), for learners new to Malay.', null, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('life-lang-012', 1, 'in_review', array['lifelong']::text[], 'malay_language', 'Bahasa Melayu asas', 'Kata ganti', 2, 'understand', 'true_false', 'True or false: "kami" and "kita" both mean "we".', null, null, 'Use Malay pronouns.', 'Bahasa Melayu for beginners (CEFR A1), for learners new to Malay.', null, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('life-lang-013', 1, 'in_review', array['lifelong']::text[], 'malay_language', 'Bahasa Melayu asas', 'Arah', 2, 'apply', 'mcq', 'What does "kanan" mean?', '[{"id":"a","text":"right (direction)"},{"id":"b","text":"left"},{"id":"c","text":"straight"}]'::jsonb, null, 'Understand directions in Malay.', 'Bahasa Melayu for beginners (CEFR A1), for learners new to Malay.', null, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('life-lang-014', 1, 'in_review', array['lifelong']::text[], 'malay_language', 'Bahasa Melayu asas', 'Kata kerja', 2, 'apply', 'mcq', 'Which word means "to eat"?', '[{"id":"a","text":"minum"},{"id":"b","text":"tidur"},{"id":"c","text":"makan"}]'::jsonb, null, 'Use common verbs in Malay.', 'Bahasa Melayu for beginners (CEFR A1), for learners new to Malay.', null, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('life-lang-015', 1, 'in_review', array['lifelong']::text[], 'malay_language', 'Bahasa Melayu asas', 'Ayat', 3, 'apply', 'fill_blank', 'Complete: "Saya ___ ke sekolah." (I go to school.)', null, null, 'Build simple Malay sentences.', 'Bahasa Melayu for beginners (CEFR A1), for learners new to Malay.', null, 'Eduventure (original questions)', 'CC BY 4.0')
insert into public.question_keys (question_id, answer, explanation, wrong, mistakes) values
  ('pri-lang-001', '"a"'::jsonb, 'We say "Good morning" before 12 noon.', '{"b":"Good night is said before going to sleep.","c":"Goodbye is said when leaving."}'::jsonb, null),
  ('pri-lang-002', '"c"'::jsonb, 'Most nouns add -s for more than one: cats.', '{"a":"More than one needs the plural form.","b":"We just add -s: cat → cats."}'::jsonb, null),
  ('pri-lang-003', '"b"'::jsonb, '"Apple" starts with a vowel sound, so we use "an".', '{"c":"Before a vowel sound (a, e, i, o, u) we use \"an\".","a":"\"An\" is used because we mean any one apple, said for the first time."}'::jsonb, null),
  ('pri-lang-004', '{"accept":["cold"]}'::jsonb, 'Hot and cold are opposites.', null, null),
  ('pri-lang-005', '"false"'::jsonb, 'Child is irregular: the plural is "children".', '{"true":"\"Childs\" is not a word; the plural of child is children."}'::jsonb, null),
  ('pri-lang-006', '"b"'::jsonb, 'With he, she and it we use "is".', '{"c":"\"Am\" goes only with \"I\".","a":"\"Are\" goes with you, we and they."}'::jsonb, null),
  ('pri-lang-007', '"a"'::jsonb, 'Under means below something.', '{"b":"On means on top of; the cat is below.","c":"In means inside something."}'::jsonb, null),
  ('pri-lang-008', '{"accept":["ten"]}'::jsonb, '7 + 3 = 10, which we write as "ten".', null, null),
  ('pri-lang-009', '["c","a","b"]'::jsonb, 'English sentences usually go: who (I) – action (like) – what (nasi lemak).', null, null),
  ('pri-lang-010', '"a"'::jsonb, '"What is your name?" asks for a name.', '{"b":"Where asks about places.","c":"When asks about time."}'::jsonb, null),
  ('pri-lang-011', '"true"'::jsonb, 'Every sentence starts with a capital letter, like "My name is Aina."', '{"false":"Sentences always start with a capital letter."}'::jsonb, null),
  ('pri-lang-012', '"b"'::jsonb, 'A clear daytime sky is blue.', '{"c":"Grass is green; a clear sky is blue.","a":"The sky is dark only at night."}'::jsonb, null),
  ('pri-lang-013', '"a"'::jsonb, 'Your mother''s mother is your grandmother (nenek).', '{"b":"An aunt is your mother''s or father''s sister.","c":"A sister has the same parents as you."}'::jsonb, null),
  ('pri-lang-014', '{"accept":["tuesday"]}'::jsonb, 'Monday, Tuesday, Wednesday…', null, null),
  ('pri-lang-015', '"b"'::jsonb, 'In the simple present, he/she/it adds -s: he walks.', '{"c":"With he, she and it the verb adds -s.","a":"\"Walking\" needs \"is\" before it."}'::jsonb, null),
  ('lsec-lang-001', '"a"'::jsonb, '"Go" is irregular: the past is "went".', '{"b":"\"Yesterday\" means the past, so we need the past form.","c":"\"Goes\" is present, for he/she/it."}'::jsonb, null),
  ('lsec-lang-002', '"c"'::jsonb, 'Short adjectives add -er (doubling the last letter): big → bigger.', '{"a":"Comparing two things needs the comparative form.","b":"\"Biggest\" compares three or more."}'::jsonb, null),
  ('lsec-lang-003', '{"accept":["bought"]}'::jsonb, '"Buy" is irregular: buy → bought.', null, null),
  ('lsec-lang-004', '"a"'::jsonb, 'For actions happening now: am/is/are + -ing.', '{"b":"\"Look!\" shows it is happening now, so we use the present continuous.","c":"It is happening now, not in the past."}'::jsonb, null),
  ('lsec-lang-005', '"false"'::jsonb, '"Information" is uncountable: we say "some information" or "a piece of information".', '{"true":"Uncountable nouns have no plural form."}'::jsonb, null),
  ('lsec-lang-006', '"b"'::jsonb, 'We use "in" with months and years.', '{"c":"\"On\" goes with days and dates.","a":"\"At\" goes with clock times."}'::jsonb, null),
  ('lsec-lang-007', '"a"'::jsonb, 'Enormous means very big, like huge.', '{"b":"Tiny is the opposite.","c":"Quick is about speed, not size."}'::jsonb, null),
  ('lsec-lang-008', '["d","a","b","c"]'::jsonb, 'Questions often go: question word – do/does – subject – verb.', null, null),
  ('lsec-lang-009', '"b"'::jsonb, '"So" introduces a result.', '{"c":"\"But\" shows a contrast, not a result.","a":"\"Because\" gives a reason; here we need the result."}'::jsonb, null),
  ('lsec-lang-010', '{"accept":["highest"]}'::jsonb, 'With "the" and three or more things, we use the superlative: highest.', null, null),
  ('lsec-lang-011', '"c"'::jsonb, '"Must" expresses a strong rule or obligation.', '{"a":"\"Might\" is only a possibility, not a rule.","b":"\"Can\" is about ability or permission, not a rule."}'::jsonb, null),
  ('lsec-lang-012', '"true"'::jsonb, 'Beautiful: b-e-a-u-t-i-f-u-l.', '{"false":"That is the correct spelling."}'::jsonb, null),
  ('lsec-lang-013', '"a"'::jsonb, 'Possessive pronouns stand alone: mine, yours, his, hers.', '{"b":"\"My\" needs a noun after it (my book).","c":"\"Me\" is an object, not a possessive."}'::jsonb, null),
  ('lsec-lang-014', '"c"'::jsonb, 'Take off = remove clothing. In many Malaysian homes we take off our shoes.', '{"a":"Put on is the opposite: wearing them.","b":"Look after means to take care of."}'::jsonb, null),
  ('lsec-lang-015', '{"accept":["knives"]}'::jsonb, 'Words ending in -fe change to -ves: knife → knives.', null, null),
  ('usec-lang-001', '"a"'::jsonb, 'Life experience: have + past participle: I have never seen snow.', '{"b":"\"Never\" with life experience uses the present perfect.","c":"Experiences are not described with the continuous."}'::jsonb, null),
  ('usec-lang-002', '"c"'::jsonb, 'Passive: object becomes subject + was/were + past participle (+ by …).', '{"a":"That changes the meaning completely.","b":"The tense must stay past, and passive uses be + past participle."}'::jsonb, null),
  ('usec-lang-003', '"b"'::jsonb, 'First conditional: If + present, will + verb.', '{"c":"\"Would\" is for unlikely or imaginary situations (second conditional).","a":"The result of a real future condition uses \"will\"."}'::jsonb, null),
  ('usec-lang-004', '{"accept":["was"]}'::jsonb, 'In reported speech the tense moves back: am → was.', null, null),
  ('usec-lang-005', '"false"'::jsonb, '"Neither" is singular: "Neither of the boys is ready."', '{"true":"\"Neither\" takes a singular verb, so it should be \"is\"."}'::jsonb, null),
  ('usec-lang-006', '"b"'::jsonb, 'Evacuate means to leave a dangerous place.', '{"c":"Evaluate means to judge something; it only looks similar.","a":"Evaporate means to turn into vapour."}'::jsonb, null),
  ('usec-lang-007', '"a"'::jsonb, 'We use "who" for people.', '{"b":"\"Which\" is for things, not people.","c":"\"Whose\" shows possession."}'::jsonb, null),
  ('usec-lang-008', '["c","a","b"]'::jsonb, 'Sequence words (first, next, finally) show the order.', null, null),
  ('usec-lang-009', '"b"'::jsonb, 'Formal letters use full words and polite, neutral language.', '{"c":"\"Hey\" and \"lah\" are too informal for a formal letter.","a":"Text spellings and strong slang are not used in formal writing."}'::jsonb, null),
  ('usec-lang-010', '{"accept":["confidence"]}'::jsonb, 'After "great" we need a noun: confident → confidence.', null, null),
  ('usec-lang-011', '"c"'::jsonb, '"A piece of cake" means something is very easy.', '{"a":"It is an idiom, not about real cake.","b":"The idiom is about how easy something is."}'::jsonb, null),
  ('usec-lang-012', '"b"'::jsonb, '"Enjoy" + verb-ing: I enjoy reading.', '{"c":"\"Enjoy\" is followed by the -ing form.","a":"After \"enjoy\" we need a gerund."}'::jsonb, null),
  ('usec-lang-013', '"true"'::jsonb, '"It''s" = "it is", so it needs an apostrophe.', '{"false":"\"It''s\" is short for \"it is\" and needs the apostrophe."}'::jsonb, null),
  ('usec-lang-014', '"c"'::jsonb, '"Despite" shows contrast: something happened even though…', '{"a":"Because of gives a cause; here the traffic did not stop us.","b":"\"So\" introduces a result and cannot start this way."}'::jsonb, null),
  ('usec-lang-015', '{"accept":["had left"]}'::jsonb, 'An earlier past action uses the past perfect: had + past participle.', null, null),
  ('life-lang-001', '"a"'::jsonb, 'Selamat pagi = Good morning.', '{"b":"Selamat malam = Good night.","c":"Selamat tinggal = Goodbye, said by the person who is leaving (the one staying says \"Selamat jalan\")."}'::jsonb, null),
  ('life-lang-002', '"c"'::jsonb, 'Terima kasih = Thank you.', '{"a":"Excuse me = Maaf / Tumpang lalu.","b":"You are welcome = Sama-sama."}'::jsonb, null),
  ('life-lang-003', '"b"'::jsonb, 'Lima = five.', '{"c":"4 is empat.","a":"6 is enam."}'::jsonb, null),
  ('life-lang-004', '{"accept":["tiga"]}'::jsonb, 'Satu (1), dua (2), tiga (3), empat (4).', null, null),
  ('life-lang-005', '"c"'::jsonb, 'Ibu = mother.', '{"a":"Father = bapa or ayah.","b":"Sister = kakak (older) or adik (younger)."}'::jsonb, null),
  ('life-lang-006', '"true"'::jsonb, 'Nasi = cooked rice, as in nasi lemak.', '{"false":"Nasi is indeed cooked rice."}'::jsonb, null),
  ('life-lang-007', '"a"'::jsonb, 'Lapar = hungry. Saya lapar = I am hungry.', '{"b":"Haus means thirsty.","c":"Penat means tired."}'::jsonb, null),
  ('life-lang-008', '["c","a","b"]'::jsonb, 'Malay says "Nama saya Adam" (name – my – Adam).', null, null),
  ('life-lang-009', '"b"'::jsonb, 'Berapa = how much; harga = price; ini = this.', '{"c":"Apa khabar = How are you?","a":"Di mana tandas = Where is the toilet?"}'::jsonb, null),
  ('life-lang-010', '{"accept":["merah"]}'::jsonb, 'Merah = red, as in the Malaysian flag colours.', null, null),
  ('life-lang-011', '"c"'::jsonb, 'Esok = tomorrow.', '{"a":"Yesterday = semalam.","b":"Today = hari ini."}'::jsonb, null),
  ('life-lang-012', '"true"'::jsonb, 'Both mean "we": kita includes the listener; kami does not.', '{"false":"Both mean we; kita includes the person you are talking to, kami does not."}'::jsonb, null),
  ('life-lang-013', '"a"'::jsonb, 'Kanan = right, kiri = left.', '{"b":"Left = kiri.","c":"Straight = terus."}'::jsonb, null),
  ('life-lang-014', '"c"'::jsonb, 'Makan = eat. "Jom makan!" = Let''s eat!', '{"a":"Minum = to drink.","b":"Tidur = to sleep."}'::jsonb, null),
  ('life-lang-015', '{"accept":["pergi"]}'::jsonb, 'Pergi = to go. Saya pergi ke sekolah = I go to school.', null, null)
